// recordingRunner delegates to inner and records the pipe each call received.
type recordingRunner struct {
	inner Runner
	pipes []string
}

func (r *recordingRunner) Run(ctx context.Context, e *Executor, p *Pipeline, idx int, cmd *Command, call CommandCall, pipe string, pipeTruncated bool) (string, bool, error) {
	r.pipes = append(r.pipes, pipe)
	return r.inner.Run(ctx, e, p, idx, cmd, call, pipe, pipeTruncated)
}

// TestExecutor_RawPipeReachesNextCLIStage proves the executor carries the
// stage output unchanged: NUL and invalid UTF-8 written by one CLI stage are
// the exact bytes the next CLI stage reads on stdin.
func TestExecutor_RawPipeReachesNextCLIStage(t *testing.T) {
	_, wl := setupWhitelist(t, "printf", "cat")
	cli := &recordingRunner{inner: &CLIRunner{Whitelist: wl}}
	claude := &mockClaudeRunner{results: []WorkerResult{{Output: "reply sent"}}}

	cmds := testCommands()
	cmds["dirty"] = &Command{Name: "dirty", Runner: "cli", Mode: "process", Binary: "printf",
		FixedArgs: []string{`a\000b\377c`}, OutputSchema: "text", Timeout: "5s"}
	cmds["echo"] = &Command{Name: "echo", Runner: "cli", Mode: "passthrough", Binary: "cat",
		OutputSchema: "text", Timeout: "5s"}

	exec := &Executor{
		Planner: &StubPlanner{Result: []CommandCall{
			{Command: "dirty", Args: map[string]any{}},
			{Command: "echo", Args: map[string]any{}},
		}},
		Commands: cmds,
		Runners:  map[string]Runner{"cli": cli, "claude": claude},
		Logger:   testLogger(),
	}

	p, err := exec.Run(context.Background(), EmailMeta{MessageID: "1", From: "[EMAIL]", Subject: "T"}, "body")
	require.NoError(t, err)
	require.Equal(t, "completed", p.Status)
	require.Len(t, cli.pipes, 2)
	assert.Equal(t, "a\x00b\xffc", cli.pipes[1])
}

// TestExecutor_AutoReplyCarriesTruncationNotice proves a capped CLI stage that
// feeds the auto-reply marks the reply partial, and that an intermediate
// capped stage hands the next CLI stage the exact bytes with no notice.
func TestExecutor_AutoReplyCarriesTruncationNotice(t *testing.T) {
	_, wl := setupWhitelist(t, "dd", "tr", "cat")

	t.Run("last stage", func(t *testing.T) {
		claude := &mockClaudeRunner{results: []WorkerResult{{Output: "reply sent"}}}
		cmds := testCommands()
		cmds["cap"] = capCommand("text")
		exec := &Executor{
			Planner:  &StubPlanner{Result: []CommandCall{{Command: "cap", Args: map[string]any{}}}},
			Commands: cmds,
			Runners:  map[string]Runner{"cli": &CLIRunner{Whitelist: wl}, "claude": claude},
			Logger:   testLogger(),
		}
		_, err := exec.Run(context.Background(), EmailMeta{MessageID: "1", From: "[EMAIL]", Subject: "T"}, "body")
		require.NoError(t, err)
		require.Len(t, claude.calls, 1)
		assert.True(t, strings.HasSuffix(claude.calls[0].Pipe, truncationNotice))
	})

	t.Run("intermediate stage", func(t *testing.T) {
		cli := &recordingRunner{inner: &CLIRunner{Whitelist: wl}}
		claude := &mockClaudeRunner{results: []WorkerResult{{Output: "reply sent"}}}
		cmds := testCommands()
		cmds["cap"] = capCommand("text")
		cmds["echo"] = &Command{Name: "echo", Runner: "cli", Mode: "passthrough", Binary: "cat",
			OutputSchema: "text", Timeout: "5s"}
		exec := &Executor{
			Planner: &StubPlanner{Result: []CommandCall{
				{Command: "cap", Args: map[string]any{}},
				{Command: "echo", Args: map[string]any{}},
			}},
			Commands: cmds,
			Runners:  map[string]Runner{"cli": cli, "claude": claude},
			Logger:   testLogger(),
		}
		_, err := exec.Run(context.Background(), EmailMeta{MessageID: "1", From: "[EMAIL]", Subject: "T"}, "body")
		require.NoError(t, err)
		require.Len(t, cli.pipes, 2)
		assert.Equal(t, 1<<20, len(cli.pipes[1]))
		assert.NotContains(t, cli.pipes[1], "truncated at 1MB")
	})
}
EOF
head -22 pipeline_test.go | grep -n strings; go vet . && gofmt -l .; go test -race -count=1 -run 'TestExecutor_' . 2>&1 | tail -30

